#include "threshold_cf.h"
#include "gh_table.h"
#include "deficit_table.h"   // generated by tools/gen_deficit_table.py
#include <cmath>
#include <algorithm>
#include <numeric>

namespace hpocl {

static constexpr double kLn2 = 0.6931471805599453;
static constexpr double kPi  = 3.141592653589793;
static constexpr double kCmod = 4.0 * kPi / kLn2;          // ~18.13 (Lemma 4)

//-----------------------------------------------------------------------------
// HPOCL_DEFICIT_TABLE -- which deficit evaluator is deployed.
//
// 1 (default): ln D from the generated table (include/deficit_table.h) for a
//     tabulated M with DFT_TLO <= t <= DFT_THI; the analytic tail ln C +
//     lnQ_asym(t) above DFT_THI; the live GH-48 rule below DFT_TLO or for an M
//     the table does not cover. This is what main.tex:169-171 describes ("log D
//     on a uniform log-gamma grid of 1600 points per modulation and branch,
//     with the analytic tail C*Q(t) beyond it") and what the A53 budget needs:
//     one log + four table reads + 15 flops per deficit instead of
//     L*ma*GH_N*L*(2*nimg+1) quadrature work.
// 0: the pre-table path exactly -- GH-48 quadrature for t <= kTQ, analytic tail
//     above kTQ. Compile with -DHPOCL_DEFICIT_TABLE=0 to restore it.
// Both paths stay compiled in under either setting: the quadrature is the
// fallback AND the reference the accuracy gates compare against (cf_bench maxq,
// tools/check_deficit_table.py), so it is never dead code.
// kernels/threshold_cf.cl and tools/cf_ref.py carry the same switch and the same
// three-way split; all three must be flipped together.
//-----------------------------------------------------------------------------
#ifndef HPOCL_DEFICIT_TABLE
#define HPOCL_DEFICIT_TABLE 1
#endif

//---------------------------------------------------------------------------
// constellation helpers
//---------------------------------------------------------------------------
namespace {
struct Axis {
  int L;                 // PAM levels per axis, L = sqrt(M)
  int ma;                // bits per axis = log2 L
  double delta;          // constellation spacing, delta^2 = 6/(M-1)
  std::vector<double> x;         // levels, ascending
  std::vector<std::vector<int>> bits;  // bits[level][bit] Gray label
};

Axis make_axis(int M) {
  Axis a;
  a.L = (int)std::lround(std::sqrt((double)M));
  a.ma = (int)std::lround(std::log2((double)a.L));
  a.delta = std::sqrt(6.0 / (M - 1.0));
  a.x.resize(a.L);
  a.bits.assign(a.L, std::vector<int>(a.ma, 0));
  for (int j = 0; j < a.L; ++j) {
    a.x[j] = (2.0 * j - (a.L - 1)) * a.delta * 0.5;
    int g = j ^ (j >> 1);                       // reflected Gray label
    for (int b = 0; b < a.ma; ++b) a.bits[j][b] = (g >> b) & 1;
  }
  return a;
}

double softplus_bits(double t) {  // log2(1 + e^{-t}), stable
  if (t < 0.0) return -t / kLn2 + std::log2(1.0 + std::exp(t));
  return std::log2(1.0 + std::exp(-t));
}

double logsumexp_neg_d2(const double* d2, int n) {  // log sum exp(-d2_i)
  double m = *std::min_element(d2, d2 + n);
  double s = 0.0;
  for (int i = 0; i < n; ++i) s += std::exp(-(d2[i] - m));
  return -m + std::log(s);
}

// E_n[f] under n ~ N(0, sigma^2) via Gauss-Hermite
template <typename F>
double gh_expect(double sigma, F&& f) {
  double acc = 0.0;
  const double rs = std::sqrt(2.0) * sigma;
  for (int i = 0; i < GH_N; ++i) acc += kGH_W[i] * f(rs * kGH_Z[i]);
  return acc / std::sqrt(kPi);
}

double axis_deficit(bool folded, double gamma, const Axis& a) {
  const double sigma2 = 1.0 / (2.0 * gamma);
  const double sigma  = std::sqrt(sigma2);
  const double inv2s2 = 0.5 / sigma2;
  const double range  = a.L * a.delta;          // modulo fold span
  const int nimg = folded ? 2 : 0;
  double acc = 0.0;
  for (int j = 0; j < a.L; ++j) {
    acc += gh_expect(sigma, [&](double n) {
      const double y = a.x[j] + n;
      double loss = 0.0;
      std::vector<double> d0, d1;
      for (int b = 0; b < a.ma; ++b) {
        d0.clear(); d1.clear();
        for (int q = 0; q < a.L; ++q) {
          for (int l = -nimg; l <= nimg; ++l) {
            double dy = y - a.x[q] - l * range;
            double d2 = dy * dy * inv2s2;
            (a.bits[q][b] == 0 ? d0 : d1).push_back(d2);
          }
        }
        double llr = logsumexp_neg_d2(d1.data(), (int)d1.size()) -
                     logsumexp_neg_d2(d0.data(), (int)d0.size());
        double t = (2.0 * a.bits[j][b] - 1.0) * llr;
        loss += softplus_bits(t);
      }
      return loss;
    });
  }
  return acc / (double)a.L;      // per-axis deficit, bits
}
}  // namespace

// Lemma-4 analytic tail: D_axis = n_nb (pi/ln2) Q(t), t = delta sqrt(gamma/2).
// The quadrature is used only while GH-48 still resolves the dominant error
// event (t <= kTQ); beyond it the deployed form is the analytic tail C*Q(t).
//
// SCOPE, since the ln-D table landed: kTQ now governs ONLY the fallback path --
// an M that include/deficit_table.h does not cover, or HPOCL_DEFICIT_TABLE=0.
// The deployed path switches quadrature -> table at DFT_TLO (1e-4, where GH-48
// is worth 1e-9 dB, so that handover is free) and table -> tail at DFT_THI
// (32, where the plain tail is worth 0.0052 dB against the 0.3046 dB measured
// below for the kTQ = 5 switch). Everything the block below measures about GH-48
// resolution, the Psi staircase and root uniqueness is still true of the
// fallback, and it is the evidence for why the table's grid starts and ends
// where it does.
//
// Measured error of each branch against a CONVERGED reference for the same
// deficit definition. Two independent references agree: (i) composite
// Gauss-Legendre in the standard-normal variable with Richardson extrapolation
// over h, h/2, h/4 (self-convergence <= 2e-11 relative), and (ii) Gauss-Hermite
// at raised order. M = 16/64/256 give identical numbers, as do the folded and
// unfolded axes, because t is the natural scaling variable:
//      t      GH-48 err     C*Q(t) err    GH-96      GH-192     GH-384
//      4.0    -0.0318 dB    +0.2684 dB
//      5.0    -0.1205       +0.1841
//      7.0    -0.6685       +0.1006
//      8.0    -0.8407       +0.0784
//      9.5    +1.6161       +0.0566       +0.2319    +0.0337    -0.0072
//     10.0    +1.9202       +0.0513
//     11.0                  +0.0427
// The branches cross at t ~ 5.3, so kTQ 5 caps the worst-case deficit error
// at 0.184 dB (0.1205 dB just inside the band, 0.1841 dB just outside). At the
// old value 10 the worst case was 1.9202 dB, reached from inside the band.
//
// WHY GH-48 degrades -- resolution, not truncation. Its outermost node is
// 8.975315 (kernels/gh_table.clh), i.e. a noise span of 12.69 sigma, and the
// dominant error event sits at n = delta/2, which is GH variable
// z = t/sqrt(2) = 6.72 at t = 9.5: comfortably INSIDE the span, so the rule is
// not blind. What fails is that the softplus hinge sharpens like
// 1/(2*sqrt(2)*t) = 0.037 in z at t = 9.5 while the local GH-48 node spacing
// there is 0.43 (pi/sqrt(2N - z^2); 0.4295 between the tabulated nodes 6.3806
// and 6.8101). The feature is 11.6x narrower than the node spacing. Raising the
// order fixes it monotonically (GH-96/192/384 column above), which a truncation
// story cannot explain -- an earlier version of this comment said the outermost
// node was "~8.0" and the contribution sat at "z ~ t"; both were wrong.
//
// What kTQ 5 buys, measured on the cf_bench pool (tools/cf_ref.py
// seed 7, 5 configs x 8 channels):
//   * The quadrature->tail switch is a HARD discontinuity in D. Its size is
//     (tail err - GH-48 err) evaluated at the switch: +0.3046 dB at kTQ 5,
//     -1.8689 dB at kTQ 10. That step propagates into Psi = ln S_fin - ln S_mod weighted by
//     the softmax weight of the switching stream, and a MOD-side switch steps Psi
//     DOWN while a FIN-side switch steps it UP, so Psi becomes a staircase.
//     Measured max |step in Psi|: 0.0709 (kTQ 5) vs 0.2584 (kTQ 10).
//   * Root uniqueness. Counting sign changes of Psi over [u0/4, 4 u0] with a
//     dense grid plus explicit probes at every switch point: exactly 1 on all 39
//     measurable channels at kTQ 5, but 11 on M=16/d=2/K=4 ch4 at kTQ 10.
//     So main.tex's "the root is therefore unique" holds for the exact deficit,
//     and empirically for the deployed piecewise one at kTQ 5 -- it is not a
//     consequence of the derivation, and at kTQ 10 it was false.
//   * Threshold accuracy vs a smooth converged reference (GH-384 in band,
//     4-term lnQ plus the measured O(t^-2) deficit correction above): worst
//     0.0961 dB over the pool at kTQ 5 (M=64/d=4/K=8 UCD ch4, flat_ratio
//     0.0759), 0.0876 dB on M=16/d=2/K=4 ch1, everything else <= 0.027 dB.
//     kTQ 10 is no better here (0.0945 / 0.0843 dB), so the win from 10 -> 5
//     is uniqueness and the bounded deficit error, not this residual.
//   * The previously quoted "0.55 dB tau error at denom = 1e-2 with kTQ 10,
//     0.000 dB with kTQ 5" does NOT reproduce: on synthetic near-flat spectra
//     with denom = g_min/eta - lam_min exactly 1e-2 (M=64/d=4/K=8 and
//     M=64/d=2/K=4), kTQ 5 and kTQ 10 give the SAME tau and both match the
//     smooth reference to <= 0.0001 dB. At denom = 3e-3 both are 2.27 dB off the
//     smooth reference, identically -- i.e. that error is the ill-conditioning
//     of the crossing, not the quadrature band.
//
// Realistic crossings do NOT all sit below kTQ. Over the cf_bench pool the
// dominant (weakest) stream reaches t = 1.9..16.0 at the root and the strongest
// stream t = 5.6..71.5, so the tail branch is active at the operating point for
// essentially every channel. An earlier comment claimed "t ~ 0.3-2, so nothing
// changes in the normal operating range"; that is wrong for this pool.
//
// Not fixed by moving kTQ, and deliberately not fixed here: the 0.3046 dB step
// itself. Two measured alternatives are recorded as a decision record in
// README.md ("Paper claims vs implementation"): (i) multiply the tail by the
// O(t^-2) term main.tex:68 already postulates, D ~ C*Q(t)*(1 - 1.20/t^2)
// (coefficient measured, residual <= 0.0002 dB for t >= 12), and switch at
// t = 4.5 -> step 0.0236 dB, worst deficit error 0.068 dB; (ii) GH_N = 192 with
// no switch -> 0.0337 dB at t = 9.5, continuous, 4x the quadrature work.
// (i) costs one multiply but introduces an identified coefficient, which
// collides with main.tex:34 "no fitted constants"; (ii) costs PL area. Neither
// is implemented.
//
// Keep in sync with tools/cf_ref.py (TQ) and kernels/threshold_cf.cl (TQ);
// tools/check_capacity.py fails the build if the three drift.
static constexpr double kTQ = 5.0;
static double q_tail(double t) { return 0.5 * std::erfc(t / std::sqrt(2.0)); }
static double c_const(bool mod, int M) {
  double L = std::sqrt((double)M);
  return mod ? kCmod : kCmod * (L - 1.0) / L;
}
static double t_of(double gamma, int M) {
  return std::sqrt(6.0 / (M - 1.0)) * std::sqrt(gamma * 0.5);
}
static double lnQ_asym(double t) {  // ln Q(t), the deployed 3-term asymptotic
  double l = -0.5 * t * t - 0.5 * std::log(2.0 * kPi) - std::log(t);
  double t2 = t * t;
  double c = 1.0 - 1.0 / t2 + 3.0 / (t2 * t2);
  return l + std::log(c > 0.0 ? c : 1.0);
}

//---------------------------------------------------------------------------
// the generated ln-D table: row selection and interpolation
//---------------------------------------------------------------------------
int deficit_table_index(int M) {
#if HPOCL_DEFICIT_TABLE
  for (int i = 0; i < DFT_NM; ++i)
    if (kDFT_M[i] == M) return i;
#else
  (void)M;
#endif
  return -1;
}

void deficit_table_grid(double* t_lo, double* t_hi, int* n_points, int* n_M) {
#if HPOCL_DEFICIT_TABLE
  if (t_lo) *t_lo = DFT_TLO;
  if (t_hi) *t_hi = DFT_THI;
  if (n_points) *n_points = DFT_N;
  if (n_M) *n_M = DFT_NM;
#else
  if (t_lo) *t_lo = 0.0;
  if (t_hi) *t_hi = 0.0;
  if (n_points) *n_points = 0;
  if (n_M) *n_M = 0;
#endif
}

#if HPOCL_DEFICIT_TABLE
// 4-point Lagrange interpolation of ln D on the uniform ln-t grid. IDENTICAL
// arithmetic, in the same order, in kernels/threshold_cf.cl dft_lookup() and
// tools/cf_ref.py _dft_lookup(); tools/gen_deficit_table.py interp_ln_deficit()
// is the reference copy. cf_bench's maxtab column compares this against the
// oracle, so a change here is a change in four places.
//
// Indexed by log(t/DFT_TLO)/DFT_DLNT rather than (log t - DFT_LNTLO)/DFT_DLNT:
// on the fp32 PL datapath the second form carries log(t)'s ~1e-6 absolute error
// into a subtraction whose result is only 12.66, i.e. 1.3e-4 grid steps
// (2.3e-3 dB of ln D at t = 32), while the ratio form logs a well-conditioned
// number and lands at 7.6e-6 steps (1.3e-4 dB). Both are ~1e-16 in fp64.
//
// The weights are the Lagrange basis prod_{m != k} (f-m)/(k-m) for nodes at
// f = 0,1,2,3: each is 1 at its own node and 0 at the other three, and they sum
// to 1, so the clamped end intervals (f in [0,1) and [2,3]) interpolate rather
// than extrapolate. Measured against the converged reference the whole grid
// costs 5.7e-6 dB worst (at t = 31.9) and 2.5e-7 dB for t <= 10.
static double dft_lookup(int row, double t) {
  double x = std::log(t / DFT_TLO) / DFT_DLNT;
  x = x < 0.0 ? 0.0 : (x > (double)(DFT_N - 1) ? (double)(DFT_N - 1) : x);
  int i0 = (int)std::floor(x) - 1;
  if (i0 < 0) i0 = 0;
  if (i0 > DFT_N - 4) i0 = DFT_N - 4;
  const double f = x - (double)i0;
  const double* y = kDFT_LND[row];
  const double w0 = -(f - 1.0) * (f - 2.0) * (f - 3.0) / 6.0;
  const double w1 = f * (f - 2.0) * (f - 3.0) / 2.0;
  const double w2 = -f * (f - 1.0) * (f - 3.0) / 2.0;
  const double w3 = f * (f - 1.0) * (f - 2.0) / 6.0;
  return w0 * y[i0] + w1 * y[i0 + 1] + w2 * y[i0 + 2] + w3 * y[i0 + 3];
}
#endif

//---------------------------------------------------------------------------
// the live GH-48 quadrature on its own: no table, no tail branch. Reference for
// the accuracy gates and fallback below DFT_TLO / for an untabulated M.
//---------------------------------------------------------------------------
double deficit_fin_quad(double gamma, int M) {
  if (!(gamma > 0.0)) return (double)std::log2((double)M);
  Axis a = make_axis(M);
  return 2.0 * axis_deficit(false, gamma, a);   // two identical PAM axes
}
double deficit_mod_quad(double gamma, int M) {
  if (!(gamma > 0.0)) return (double)std::log2((double)M);
  Axis a = make_axis(M);
  return 2.0 * axis_deficit(true, gamma, a);
}

//---------------------------------------------------------------------------
// the deployed deficits: which of the three evaluators applies
//---------------------------------------------------------------------------
// One selector for both the linear and the log-domain form, so the two cannot
// take different branches at the same (gamma, M). They used to be written as
// four near-copies; a branch that differs between deficit_fin and
// ln_deficit_fin makes the host solve a different Psi from the one the linear
// form describes, which is the class of bug that cost 2.78e-5 dB of systematic
// maxtau once already (see the note in runtime/cf_main.cpp).
enum DeficitBranch { kDftTable = 0, kDftTail = 1, kDftQuad = 2 };

// Returns the branch and, through the out-params, the table row group of M
// (-1 when untabulated; the caller adds the branch offset) and t. gamma <= 0
// gives t = NaN, which fails every comparison and lands on kDftQuad, where the
// quadrature's own guard saturates the deficit at log2(M) -- exactly the
// pre-table behaviour, including for ln_deficit_*, which has no gamma guard.
static DeficitBranch deficit_branch(double gamma, int M, int* mi_out, double* t_out) {
  const double t = t_of(gamma, M);
  *t_out = t;
  *mi_out = -1;
#if HPOCL_DEFICIT_TABLE
  const int mi = deficit_table_index(M);
  if (mi >= 0) {
    *mi_out = mi;
    if (t >= DFT_TLO && t <= DFT_THI) return kDftTable;
    if (t > DFT_THI) return kDftTail;
    return kDftQuad;      // below the grid: GH-48, worth 1.1e-4 dB at t = 2 and
  }                       // 1e-9 dB at the grid edge, so this handover is free
#endif
  return t > kTQ ? kDftTail : kDftQuad;
}

static double ln_deficit_impl(bool mod, double gamma, int M) {
  double t; int mi;
  switch (deficit_branch(gamma, M, &mi, &t)) {
#if HPOCL_DEFICIT_TABLE          // with the table off the selector never
    case kDftTable: return dft_lookup(2 * mi + (mod ? 1 : 0), t);
#endif                           // returns kDftTable, and dft_lookup (which is
                                 // the only reference to kDFT_LND) stays out of
                                 // the binary, so -DHPOCL_DEFICIT_TABLE=0 also
                                 // restores the pre-table footprint
    case kDftTail:  return std::log(c_const(mod, M)) + lnQ_asym(t);
    default:        return std::log(mod ? deficit_mod_quad(gamma, M)
                                        : deficit_fin_quad(gamma, M));
  }
}

// Linear domain. The tail keeps the erfc form (NOT exp(ln C + lnQ_asym)): the
// two differ by 3.4e-3 dB at t = 5 and cf_bench's maxq column compares this
// value against the oracle's, so it stays bit-for-bit what it was.
static double deficit_impl(bool mod, double gamma, int M) {
  double t; int mi;
  switch (deficit_branch(gamma, M, &mi, &t)) {
#if HPOCL_DEFICIT_TABLE
    case kDftTable: return std::exp(dft_lookup(2 * mi + (mod ? 1 : 0), t));
#endif
    case kDftTail:  return 2.0 * (c_const(mod, M) / 2.0) * q_tail(t);
    default:        return mod ? deficit_mod_quad(gamma, M)
                               : deficit_fin_quad(gamma, M);
  }
}

double deficit_fin(double gamma, int M) {
  if (!(gamma > 0.0)) return (double)std::log2((double)M);
  return deficit_impl(false, gamma, M);
}
double deficit_mod(double gamma, int M) {
  if (!(gamma > 0.0)) return (double)std::log2((double)M);
  return deficit_impl(true, gamma, M);
}

double ln_deficit_fin(double gamma, int M) {
  return ln_deficit_impl(false, gamma, M);
}
double ln_deficit_mod(double gamma, int M) {
  return ln_deficit_impl(true, gamma, M);
}

//---------------------------------------------------------------------------
// branch rates / crossing function
//---------------------------------------------------------------------------
namespace {
inline double eta_factor(int d, int M) { return 1.0 + (double)(d - 1) / ((double)d * (M - 1.0)); }
inline double delta2(int M) { return 6.0 / (M - 1.0); }

// per-user THP equal-output SINR gamma^*_k and d gtilde/d rho
void thp_point(const double* lam_u, int d, double rho, ThpVariant v,
               double* gam, double* dgdrho, double eta) {
  // returns gamma^* (per-stream post-precoding SINR) and d gamma^*/d rho.
  // GMD:       gamma^* = rho g / eta
  // MMSE-UCD:  gamma^* = [ (prod_i (1+rho lam_i))^{1/d} - 1 ] / eta
  //            (the "equal-output form" gtilde(u) of eq.(phi) is gamma^*/rho)
  if (v == ThpVariant::kGMD) {
    double lg = 0.0;
    for (int i = 0; i < d; ++i) lg += std::log(std::max(lam_u[i], 1e-12));
    double g = std::exp(lg / d);
    *gam = rho * g / eta;
    *dgdrho = g / eta;
    return;
  }
  double p = 1.0, msum = 0.0;
  for (int i = 0; i < d; ++i) {
    p *= (1.0 + rho * lam_u[i]);
    msum += lam_u[i] / (1.0 + rho * lam_u[i]);
  }
  double geq = std::pow(p, 1.0 / d) - 1.0;
  *gam = geq / eta;
  *dgdrho = (1.0 + geq) * (msum / d) / eta;
}
}  // namespace

// NOTE (dead but documented): phi_sums/phi_u/phi_du implement exactly the
// Phi'(u) formula of main.tex:157-165, including D'(gamma) = (D/gamma) dlogD/dloggamma
// and the UCD feedback term. Nothing calls them -- the deployed solver works on
// the log-domain balance Psi = ln S_fin - ln S_mod (psi_u/psi_du below), which
// has the same root set as Phi = S_fin - S_mod but neither cancels nor underflows
// in fp32. They are kept because the paper documents this form; if they are ever
// removed, main.tex:157-165 loses its only implementation.
void phi_sums(double u, const double* lam, const CfConfig& c,
              double* Sfin, double* Smod, double* dSfin, double* dSmod) {
  const double d2 = delta2(c.M);
  const double rho = 4.0 * u / d2;
  const double eta = eta_factor(c.d, c.M);
  const double h = 1e-4;
  double sf = 0.0, sm = 0.0, dsf = 0.0, dsm = 0.0;
  for (int k = 0; k < c.K; ++k) {
    const double* lu = lam + (size_t)k * c.d;
    for (int i = 0; i < c.d; ++i) {
      double g = 4.0 * u * lu[i] / d2;
      double D = deficit_fin(g, c.M);
      sf += D;
      // g == 0 (a dead stream, lam[i] == 0) makes D/g = log2(M)/0 = +inf while
      // lu[i] == 0, so the product below is 0 * inf = NaN. Skipping is exact,
      // not an approximation: D is pinned to log2(M) by the deficit guard for
      // every u, so dD/du = 0 and lam[i] * D'(g) = 0 anyway. Measured before the
      // guard: phi_u finite (-12.9406) but phi_du = NaN for
      // lam = [[1,.5,.25,0],[1,1,1,1]] at u = 1 and u = 10, M = 64.
      if (g > 0.0) {
        double dlog = (std::log(deficit_fin(g * (1.0 + h), c.M)) -
                       std::log(deficit_fin(g * (1.0 - h), c.M))) / (2.0 * h);
        dsf += lu[i] * (D / g) * dlog;
      }
    }
    double gm, dgdrho;
    thp_point(lu, c.d, rho, c.variant, &gm, &dgdrho, eta);
    double D = deficit_mod(gm, c.M);
    sm += (double)c.d * D;                       // R_THP = Tm - d * sum_k D_mod
    // same 0 * inf guard: gm == 0 for a dead user (GMD with lam == 0, or UCD
    // with prod(1 + rho*lam) == 1) and dgdrho is 0 there, so the term is 0.
    if (gm > 0.0) {
      double dlog = (std::log(deficit_mod(gm * (1.0 + h), c.M)) -
                     std::log(deficit_mod(gm * (1.0 - h), c.M))) / (2.0 * h);
      dsm += (double)c.d * dgdrho * (D / gm) * dlog;
    }
  }
  *Sfin = sf; *Smod = sm;
  *dSfin = (4.0 / d2) * dsf;
  *dSmod = (4.0 / d2) * dsm;
}

double phi_u(double u, const double* lam, const CfConfig& c) {
  double sf, sm, dsf, dsm;
  phi_sums(u, lam, c, &sf, &sm, &dsf, &dsm);
  return sf - sm;
}

double phi_du(double u, const double* lam, const CfConfig& c) {
  double sf, sm, dsf, dsm;
  phi_sums(u, lam, c, &sf, &sm, &dsf, &dsm);
  return dsf - dsm;
}

// log-domain balance: Psi(u) = ln Sfin(u) - ln Smod(u), evaluated with
// log-sum-exp over per-stream log-deficits. Cancellation-free AND
// underflow-free: the fp32 PL datapath solves Newton on this form.
double psi_u(double u, const double* lam, const CfConfig& c) {
  const double d2 = delta2(c.M);
  const double rho = 4.0 * u / d2;
  const double eta = eta_factor(c.d, c.M);
  double mf = -1e300, mm = -1e300;
  std::vector<double> lf((size_t)c.K * c.d), lm(c.K);
  for (int k = 0; k < c.K; ++k) {
    const double* lu = lam + (size_t)k * c.d;
    for (int i = 0; i < c.d; ++i) {
      lf[(size_t)k * c.d + i] = ln_deficit_fin(4.0 * u * lu[i] / d2, c.M);
      mf = std::max(mf, lf[(size_t)k * c.d + i]);
    }
    double gm, dg;
    thp_point(lu, c.d, rho, c.variant, &gm, &dg, eta);
    lm[k] = std::log((double)c.d) + ln_deficit_mod(gm, c.M);
    mm = std::max(mm, lm[k]);
  }
  double sf = 0.0, sm = 0.0;
  for (auto v : lf) sf += std::exp(v - mf);
  for (auto v : lm) sm += std::exp(v - mm);
  return (mf + std::log(sf)) - (mm + std::log(sm));
}

double psi_du(double u, const double* lam, const CfConfig& c) {
  // exact-style derivative: dPsi/du = sum_i w_i dlnD_i/du - sum_k v_k dlnD_k/du
  // with softmax weights w = D_i/Sfin; per-term log-derivatives by centered
  // difference in log domain (stable, no cancellation, no underflow).
  const double d2 = delta2(c.M);
  const double eta = eta_factor(c.d, c.M);
  const double h = 1e-3;
  const double up = u * (1.0 + h), dn = u * (1.0 - h);
  const int nf = c.K * c.d;
  std::vector<double> lf(nf), lfu(nf), lfd(nf), lm(c.K), lmu(c.K), lmd(c.K);
  auto fill = [&](double uu, std::vector<double>& f, std::vector<double>& m) {
    double rhou = 4.0 * uu / d2;
    for (int k = 0; k < c.K; ++k) {
      const double* lu = lam + (size_t)k * c.d;
      for (int i = 0; i < c.d; ++i)
        f[(size_t)k * c.d + i] = ln_deficit_fin(4.0 * uu * lu[i] / d2, c.M);
      double gm, dg;
      thp_point(lu, c.d, rhou, c.variant, &gm, &dg, eta);
      m[k] = std::log((double)c.d) + ln_deficit_mod(gm, c.M);
    }
  };
  fill(u, lf, lm); fill(up, lfu, lmu); fill(dn, lfd, lmd);
  double mf = lf[0], mm = lm[0];
  for (auto v : lf) mf = std::max(mf, v);
  for (auto v : lm) mm = std::max(mm, v);
  double sf = 0, sm = 0;
  for (auto v : lf) sf += std::exp(v - mf);
  for (auto v : lm) sm += std::exp(v - mm);
  double duu = up - dn;
  double acc = 0.0;
  for (int i = 0; i < nf; ++i)
    acc += (std::exp(lf[i] - mf) / sf) * ((lfu[i] - lfd[i]) / duu);
  for (int k = 0; k < c.K; ++k)
    acc -= (std::exp(lm[k] - mm) / sm) * ((lmu[k] - lmd[k]) / duu);
  return acc;
}

//---------------------------------------------------------------------------
// LMMSE front end
//---------------------------------------------------------------------------
double lmmse_eps_s(const double* eig_prior, int n, double nv) {
  double num = 0.0, den = 0.0;
  for (int j = 0; j < n; ++j) {
    num += eig_prior[j] * nv / (eig_prior[j] + nv);
    den += eig_prior[j];
  }
  return den > 0.0 ? num / den : 0.0;
}
void shrink_spectrum(const double* lam_hat, int n, double rho, double eps_s,
                     double* lam_t) {
  for (int j = 0; j < n; ++j)
    lam_t[j] = lam_hat[j] / (1.0 + rho * lam_hat[j] * eps_s);
}

//---------------------------------------------------------------------------
// closed form + safeguarded Newton
//---------------------------------------------------------------------------
namespace {
double scan_root(const double* lam, const CfConfig& c) {
  // near-flat fallback: first sign change of Psi on a fixed geometric grid
  // over u in [1e-6, 1e6] (tau in [-36, +84] dB for M = 64, T = 32). The dead
  // band matters: a near-flat spectrum leaves Psi at round-off level over a
  // wide range, where its sign is noise rather than a branch ordering.
  const double ratio = std::pow(1e12, 1.0 / 400.0), eps = 1e-6;
  double u = 1e-6, u_neg = -1.0;
  for (int i = 0; i <= 400; ++i, u *= ratio) {
    double f = psi_u(u, lam, c);
    if (f <= -eps) u_neg = u;
    else if (f >= eps && u_neg > 0.0) return 0.5 * (u_neg + u);
  }
  return -1.0;
}
}  // namespace

CfResult threshold_closed_form(const double* lam, const CfConfig& c) {
  CfResult r;
  const int T = c.K * c.d;
  // Host mirror of the kernel's entry guard (kernels/threshold_cf.cl,
  // threshold_cf()): refuse the same shapes with flag 4 + NaN so the PS path
  // cannot hand back a threshold the PL kernel would have rejected. The L*L == M
  // test is in the kernel too: for a non-square M all three implementations
  // silently build an L = round(sqrt(M)) level constellation with
  // ma = round(log2 L) bits against a log2(M) bit label entropy, which is wrong
  // in absolute terms even though host, device and oracle agree on it.
  // lround (host) and rint (device) cannot differ here: sqrt of an integer is
  // never exactly k + 0.5.
  const int Lchk = (int)std::lround(std::sqrt((double)c.M));
  if (T < 1 || T > kCapMaxT || c.K > kCapMaxK || c.d < 1 || c.M < 4 ||
      Lchk * Lchk != c.M || 5 * ((Lchk + 1) / 2) > kCapMaxD) {
    r.flag = 4;
    r.tau_cf_dB = r.tau_dB = r.u_star = std::nan("");
    return r;
  }
  const double eta = eta_factor(c.d, c.M);
  double lam_min = lam[0];
  for (int i = 1; i < T; ++i) lam_min = std::min(lam_min, lam[i]);
  int mult = 0;
  for (int i = 0; i < T; ++i)
    if (std::fabs(lam[i] - lam_min) <= 1e-9 * std::max(1.0, lam_min)) ++mult;
  if (mult == 0) mult = 1;

  double g_min = 1e300;
  for (int k = 0; k < c.K; ++k) {
    double lg = 0.0;
    for (int i = 0; i < c.d; ++i)
      lg += std::log(std::max(lam[(size_t)k * c.d + i], 1e-12));
    g_min = std::min(g_min, std::exp(lg / c.d));
  }

  const int L = (int)std::lround(std::sqrt((double)c.M));
  const double cfin = kCmod * (L - 1.0) / L;
  const double denom = g_min / eta - lam_min;
  double u0;
  if (denom > 1e-12) {
    double num = std::log((double)c.d * kCmod / ((double)mult * cfin)) -
                 0.5 * std::log(g_min / (eta * lam_min));
    u0 = num / denom;
  } else {
    u0 = -1.0;
  }
  if (!(u0 > 0.0)) { u0 = scan_root(lam, c); r.flag = u0 > 0.0 ? 1 : 2; }
  r.fell_back = (r.flag == 1);
  if (!(u0 > 0.0)) {
    // Psi keeps one sign over the whole scan: the branch ordering is uniform,
    // so the threshold saturates. Psi > 0 means the THP deficit is the smaller
    // one (THP always wins -> tau = -inf); Psi < 0 -> always SVD (+inf).
    // INFINITY, not HUGE_VAL: HUGE_VAL is DBL_MAX, so std::isinf() was false on
    // the saturated value and every consumer that tests isinf -- err_tau() in
    // cf_main.cpp and lmmse_main.cpp, and the "(sat)" annotation in
    // lmmse_main.cpp -- mis-classified it as a finite threshold.
    const double inf = psi_u(1.0, lam, c) > 0.0 ? -INFINITY : INFINITY;
    r.tau_cf_dB = r.tau_dB = inf;
    return r;
  }

  const double d2 = delta2(c.M);
  r.u_star = u0;
  r.tau_cf_dB = 10.0 * std::log10(4.0 * T * (c.M - 1.0) * u0 / 6.0);

  // safeguarded Newton on the log-domain balance. Bracket starts at the
  // paper's [u0/4, 4 u0] and is extended geometrically until it provably
  // brackets the sign change (ill-conditioned spectra can put the root
  // outside the nominal bracket; the safeguard would otherwise reject the
  // correct Newton direction and degrade to bisection).
  double lo = u0 / 4.0, hi = u0 * 4.0;
  for (int e = 0; e < 6 && psi_u(lo, lam, c) > 0.0; ++e) lo /= 4.0;
  for (int e = 0; e < 6 && psi_u(hi, lam, c) < 0.0; ++e) hi *= 4.0;
  double u = u0;
  int used = 0;
  for (int it = 0; it < c.newton_iters; ++it) {
    double f = psi_u(u, lam, c);
    if (f <= 0.0) lo = u; else hi = u;
    double fp = psi_du(u, lam, c);
    double un = u - f / (fp != 0.0 ? fp : 1.0);
    if (!(un > lo && un < hi)) un = 0.5 * (lo + hi);
    u = un; ++used;
  }
  r.u_star = u;
  r.tau_dB = 10.0 * std::log10(4.0 * T * (c.M - 1.0) * u / 6.0);
  r.newton_used = used;
  (void)d2;
  return r;
}

CfResult threshold_deploy_lmmse(const double* lam_hat, double eps_s,
                                const CfConfig& c) {
  const int T = c.K * c.d;
  std::vector<double> lam_t(T);
  CfResult r = threshold_closed_form(lam_hat, c);
  double rho = std::pow(10.0, r.tau_dB / 10.0) / (double)T;
  for (int it = 0; it < c.shrink_iters; ++it) {
    shrink_spectrum(lam_hat, T, rho, eps_s, lam_t.data());
    r = threshold_closed_form(lam_t.data(), c);
    rho = std::pow(10.0, r.tau_dB / 10.0) / (double)T;
  }
  return r;
}

}  // namespace hpocl
